<template>
    <div class="layout-px-spacing">  
        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                            <li class="breadcrumb-item active" aria-current="page"><span>location</span></li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>


        <h5 class="text-center">ERP ATTACHMENTS</h5>




        <div class="d-flex me-4 mt-2 ">
                        <div class="ms-auto">
                            <button class="btn btn-primary " @click="add_attachment =! add_attachment">                           
                                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
  <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
  <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
</svg>
</button>
 
                        </div>
                    </div>

       
         <!-- item registration form starts -->
 <form v-if="add_attachment" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="addAttachment()">
        <h6 class="text-center">ATTACHMENT REGISTRATION FORM</h6>
        <div class="row mb-2">
            <div class="col-md-4">
                <label class="form-label">Date</label>
                <input type="date" v-model="date" class="form-control" placeholder="Enter date">
            </div>

            <div class="col-md-4">
              <label class="form-label">Attachment</label>
                  <input 
                    type="file" 
                    class="form-control" 
                    @change="handleAttachmentUpload"
                    required
                  >
            </div>
            <div class="col-md-4">
                <label class="form-label">name</label>
               <input type="text" v-model="attachmentDescription" class="form-control" placeholder="Descriptions">
            </div>
        </div>
        <div class="text-center gap-2 justify-content-end">
            <button type="button" class="btn btn-danger me-3" @click="add_attachment = false; closeEditModal()">Cancel</button>
            <button type="submit" class="btn btn-primary" :disabled="uploadingAttachment">
                <span v-if="uploadingAttachment" class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>
                <span v-else>Register</span>
            </button>
        </div>
    </form>
             <!-- item registration form ends-->

      <div class="row layout-top-spacing ">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel br-6 p-0">
                    <div v-if="loadingAttachments" v-html="tableShimmer()"></div>
                    <div v-else class="custom-table shadow">
                        <v-client-table :data="attachments" :columns="attachmentColumns" :options="table_option">
                             <template
                             #actions="props" >
                                <div class="d-flex justify-content-center align-items-center">
                                  <a 
                  :href="`${props.row.attachment}`" 
                  target="_blank"
                  title="View Attachment"
                  class="me-3"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-eye text-primary" viewBox="0 0 16 16" style="cursor: pointer;">
                    <path d="M16 8s-3-5.5-8-5.5S0 8 0 8s3 5.5 8 5.5S16 8 16 8M1.173 8a13 13 0 0 1 1.66-2.043C4.12 4.668 5.88 3.5 8 3.5s3.879 1.168 5.168 2.457A13 13 0 0 1 14.828 8q-.086.13-.195.288c-.335.48-.83 1.12-1.465 1.755C11.879 11.332 10.119 12.5 8 12.5s-3.879-1.168-5.168-2.457A13 13 0 0 1 1.172 8z"/>
                    <path d="M8 5.5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5M4.5 8a3.5 3.5 0 1 1 7 0 3.5 3.5 0 0 1-7 0"/>
                  </svg>
                </a>

                

                <a href="javascript:void(0);" @click="openEditModal(props.row)" data-bs-toggle="modal" :data-bs-target="'#edit-attachment-modal'">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-pencil-square text-success" viewBox="0 0 16 16">
  <path d="M15.502 1.94a.5.5 0 0 1 0 .706L14.459 3.69l-2-2L13.502.646a.5.5 0 0 1 .707 0l1.293 1.293zm-1.75 2.456-2-2L4.939 9.21a.5.5 0 0 0-.121.196l-.805 2.414a.25.25 0 0 0 .316.316l2.414-.805a.5.5 0 0 0 .196-.12l6.813-6.814z"/>
  <path fill-rule="evenodd" d="M1 13.5A1.5 1.5 0 0 0 2.5 15h11a1.5 1.5 0 0 0 1.5-1.5v-6a.5.5 0 0 0-1 0v6a.5.5 0 0 1-.5.5h-11a.5.5 0 0 1-.5-.5v-11a.5.5 0 0 1 .5-.5H9a.5.5 0 0 0 0-1H2.5A1.5 1.5 0 0 0 1 2.5z"/>
</svg>
                </a>

                                </div>
                            </template> 
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

        <!-- Edit attachment modal starts -->
<div class="modal fade mymodal" id="edit-attachment-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editLocationModalLabel" aria-hidden="true">
  <div class="modal-dialog modal-xl">
    <div class="modal-content">
      <div class="modal-header">
        <h1 class="modal-title fs-5" id="editLocationModalLabel">Update Attachment</h1>
        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closeEditModal()"></button>
      </div>
      <form @submit.prevent="updateAttachment()">
        <div class="modal-body">
            <div class="row mb-3">
                <div class="col-md-6">
                <label for="name">name</label>
              <input type="text" v-model="attachmentDescription" class="form-control" placeholder="name">
            </div>
            <div class="col-md-6">
              <label class="form-label">Attachment</label>
                  <input 
                    type="file" 
                    class="form-control" 
                    @change="handleAttachmentUpload"
                    required
                  >
            </div>
          </div>
        </div>
        <div class="modal-footer">
          <button type="button" class="btn btn-secondary" data-bs-dismiss="modal" @click="closeEditModal()" id="close_editing">Close</button>
          <button type="submit" class="btn btn-primary">
            <span v-if="loading_spinner" class="spinner-border spinner-border-sm text-white me-2" role="status"></span>
            Edit
          </button>
        </div>
      </form>
    </div>
  </div>
</div>
<!-- Edit attachment modal ends -->;
      
    </div>
</template>



<script setup>
    import { onMounted, ref, inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    
    useMeta({ title: 'Erp attachments' });  
    const showConfirmation = inject('showConfirmation');
    const showMessage = inject('showMessage');
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const user_id = JSON.parse(localStorage.getItem("user")).id;
    const formatDate = inject('formatDate');
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner'); 
    
    const loading_spinner = ref(false);
    const columns = ref(['SNo','name','actions']);    
    const name = ref('');
    const items = ref([]);
    const location = ref([]);
    
    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

 
const loadingAttachments = ref('');
const attachments = ref([]);
const getAttachments = async (showSpinner=true) => {
    if(showSpinner) {
        loadingAttachments.value = true;
    }
    try {
        const response = await axiosInstance.get(`attachments?type=erp-attachments`);
        attachments.value = response.data.map((item, index) => ({
            ...item,
            Sno: index + 1,
            attachment : process.env.VUE_APP_API_BASE_URL + '../../' + item.path,  
            date: formatDate(item.date),
            name: item.description
        }));
    } catch (error) {
        showError(error.message);
        console.log(error);
    }finally{
        if(showSpinner) {
            loadingAttachments.value = false; 
        }
    }
};

const handleAttachmentUpload = (e) => {
    attachment.value = e.target.files[0];
};
const attachment = ref(null);
const attachmentDescription = ref('');
const date = ref('');
const attachmentColumns = ref (['Sno','name','date','actions'])
const uploadingAttachment = ref(false);
const addAttachment = async () => {
    uploadingAttachment.value = true;
    const formData = new FormData();
    formData.append('date', date.value);
    formData.append('description', attachmentDescription.value);
    formData.append('issuer_id', user_id);
    formData.append('path', attachment.value);
    formData.append('type', 'erp-attachments');

    try {
        const response = await axiosInstance.post(
            'attachments',
            formData,
            { headers: { 'Content-Type': 'multipart/form-data' } }
        );
        
        showMessage('attachment uploaded successfully!');
        getAttachments();
        cancelAttachmentUpload();
        
    } catch (error) {
        showError(error.message);
        console.log(error);
    } finally {
        uploadingAttachment.value = false;
    }
};

const add_attachment = ref(false);

const cancelAttachmentUpload = () => {
    add_attachment.value = false;
    date.value = '';
    attachmentDescription.value = '';
    attachment.value = null;
    const fileInput = document.querySelector('input[type="file"]');
    if (fileInput) fileInput.value = '';
};


const selectedAttachment = ref(null);
const openEditModal = (attachment) => {
    console.log('Editing attachment:', attachment);
    selectedAttachment.value = attachment;
    attachmentDescription.value = attachment.name;
};

const closeEditModal = () => {
    attachmentDescription.value = '';
    selectedAttachment.value = null;
};

const updateAttachment = async () => {
    loading_spinner.value = true;

    const formData = new FormData();
    formData.append('_method', 'PUT'); 
    formData.append('description', attachmentDescription.value);
    formData.append('issuer_id', user_id);

    if (attachment.value) {
        formData.append('path', attachment.value);
    }

    try {
        const response = await axiosInstance.post(
            `attachments/${selectedAttachment.value.id}`,
            formData,
            { headers: { 'Content-Type': 'multipart/form-data' } }
        );

        showMessage('Attachment updated successfully!');
        document.getElementById('close_editing').click();
        getAttachments(false);
        closeEditModal();

    } catch (error) {
        showError(error.message);
        console.log(error);
    } finally {
        loading_spinner.value = false;
    }
};

    onMounted(() => {
        getAttachments();
    });
</script>